const binaryData = $input.item.binary;
const fileKey = Object.keys(binaryData)[0];
const base64Data = binaryData[fileKey].data;
const mimeType = binaryData[fileKey].mimeType || 'image/jpeg';

// Retrieve document ID from the earlier metadata fetch
const documentId = $('Fetch Document Metadata').item.json.id;

const prompt = `You are an accounting assistant. Extract the following fields from this receipt or invoice. Return valid JSON only — no prose, no markdown fences.

Fields:
- vendor_name: string
- vendor_vat_number: string or null
- date: ISO 8601 date (YYYY-MM-DD)
- total_amount: number including VAT
- vat_amount: number or null
- currency: ISO 4217 code e.g. EUR
- category: one of [office_supplies, travel, meals, software, marketing, utilities, professional_services, other]
- description: short string describing what was purchased
- confidence: one of [high, medium, low] reflecting overall certainty across all fields

Use null for any field that cannot be determined.`;

const payload = {
  model: 'claude-sonnet-4-6',
  max_tokens: 1024,
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'image',
          source: {
            type: 'base64',
            media_type: mimeType,
            data: base64Data
          }
        },
        {
          type: 'text',
          text: prompt
        }
      ]
    }
  ]
};

return { json: { documentId, claudePayload: JSON.stringify(payload) } };

const response = $input.item.json;
const text = response.content[0].text;

// Strip markdown code fences if Claude adds them
const jsonMatch = text.match(/```(?:json)?\n?([\s\S]*?)\n?```/) || [null, text];
const jsonStr = jsonMatch[1].trim();

let extracted;
try {
  extracted = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('Failed to parse Claude response as JSON. Raw response: ' + text);
}

const documentId = $('Build Claude Request').item.json.documentId;

return {
  json: {
    document_id: documentId,
    date: extracted.date ?? null,
    vendor_name: extracted.vendor_name ?? null,
    description: extracted.description ?? null,
    total_amount: extracted.total_amount ?? null,
    vat_amount: extracted.vat_amount ?? null,
    currency: extracted.currency ?? null,
    category: extracted.category ?? null,
    vendor_vat_number: extracted.vendor_vat_number ?? null,
    confidence: extracted.confidence ?? 'low',
    processed_at: new Date().toISOString(),
    reviewed: false
  }
};
